def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent defections so far
    opp_d = sum(1 for h in history if h[1] == 'D')

    # Endgame: defect only in the final round to avoid retaliation
    if n >= 99:
        return 'D'

    # Probing phase: only while opponent has never defected
    if opp_d == 0:
        if n < 10:
            return 'C'
        if n % 10 == 0:
            return 'D'
        return 'C'

    # Normal mode: opponent has defected at least once
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        # If we have defected recently, apologize by cooperating
        recent_my_d = sum(1 for h in history[-5:] if h[0] == 'D')
        if recent_my_d > 0:
            return 'C'
        return 'D'
    else:
        return 'C'
